-- Promociones bancarias de supermercados (reintegros y descuentos por banco/billetera).
-- Lectura pública; sólo se escriben con la service key (scripts / SQL editor).
CREATE TABLE public.bank_promos (
  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  medio TEXT NOT NULL,                -- banco o billetera: "Galicia", "Mercado Pago"...
  cadena TEXT NOT NULL,               -- "Carrefour", "Coto", "DIA" o "Todas"
  aplica_a TEXT[] NOT NULL DEFAULT '{}', -- formatos/banderas puntuales; vacío = toda la cadena
  dias TEXT[] NOT NULL DEFAULT '{}',  -- "lunes".."domingo"; vacío = todos los días
  descuento NUMERIC,                  -- porcentaje
  tipo TEXT,                          -- "reintegro", "descuento", "cuotas"...
  tope NUMERIC,
  tope_periodo TEXT,                  -- "mes", "semana", "compra"...
  minimo_compra NUMERIC,
  requisitos TEXT,
  online BOOLEAN,                     -- true = sólo online; false = sólo presencial; NULL = ambos/no se sabe
  vigencia_desde DATE,
  vigencia_hasta DATE,
  fuente TEXT,
  confianza TEXT,                     -- "alta", "media", "baja"
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),
  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()
);

ALTER TABLE public.bank_promos ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Anyone can view bank promos" ON public.bank_promos FOR SELECT USING (true);

CREATE INDEX bank_promos_vigencia_idx ON public.bank_promos (vigencia_hasta);

