INSERT INTO public.bank_promos
  (medio, cadena, aplica_a, dias, descuento, tipo, tope, tope_periodo, minimo_compra, requisitos, online, vigencia_desde, vigencia_hasta, fuente, confianza)
VALUES
  ('Galicia', 'Carrefour', ARRAY['Hipermercado Carrefour', 'Carrefour Market', 'Carrefour Express'], ARRAY['miércoles'], 10, 'reintegro', 10000, 'mes', 20000, 'Promo MODO (Banco Galicia figura entre las entidades adheridas). Requiere cuenta en Banco Galicia asociada a MODO y no tener mora. No aplica pagos con transferencia. Sólo pagando con QR de MODO (App Galicia o App MODO) con tarjeta de crédito, débito o prepaga Galicia. Tope $10.000 por banco por mes. Sólo presencial; no Carrefour Maxi. Acumulable con otros descuentos bancarios. Reintegro dentro de 30 días. Vigencia corta: termina el miércoles 25/11 (o al agotarse el cupo total).', false, '2026-11-18', '2026-11-25', 'https://www.modo.com.ar/promos/carrefour-hiper-market-express-nov26', 'alta'),
  ('Galicia', 'Coto', '{}', ARRAY['martes'], 25, 'reintegro', NULL, NULL, NULL, 'Pagando con QR de MODO desde App Galicia o App MODO con Tarjeta Galicia Débito Visa, Visa o Mastercard Galicia (crédito), en un pago. No aplica dinero en cuenta/transferencia ni Visa Business/Rural. Reintegro en caja de ahorro dentro de 10 días hábiles. Requiere caja de ahorro Galicia. Tope por cliente, incluye adicionales. Sin tope. Es la promo MODO de Coto: sólo locales físicos (no coto.com.ar), no NFC, no Amex; excluye carnes, pollo, gaseosas Coca-Cola, leches infantiles, harina, azúcar, aceite y productos con otras promos. No acumulable.', false, '2026-11-17', '2026-11-30', 'https://beneficios.galicia.ar/promocion/190981%7Ccoto%7Cmarca', 'alta'),
  ('Galicia', 'DIA', '{}', ARRAY['viernes', 'sábado'], 20, 'reintegro', 20000, 'mes', 35000, 'Pagando con QR de MODO desde App Galicia o App MODO con Tarjeta Galicia Débito Visa, Visa o Mastercard Galicia (crédito), en un pago. No aplica dinero en cuenta/transferencia ni Visa Business/Rural. Reintegro en caja de ahorro dentro de 10 días hábiles. Requiere caja de ahorro Galicia. Tope por cliente, incluye adicionales. Tope $20.000 por mes. Según T&C de MODO también vale botón MODO online y MODO Contactless (NFC, sólo Android). No acumulable según Galicia (MODO dice acumulable con otras promos MODO).', true, '2026-11-12', '2026-12-31', 'https://beneficios.galicia.ar/promocion/190709%7Cdia%7Cmarca', 'alta'),
  ('Galicia', 'Changomás', ARRAY['Changomás', 'Hiper Changomás'], ARRAY['lunes'], 20, 'reintegro', 25000, 'mes', 35000, 'Pagando con QR de MODO desde App Galicia o App MODO con Tarjeta Galicia Débito Visa, Visa o Mastercard Galicia (crédito), en un pago. No aplica dinero en cuenta/transferencia ni Visa Business/Rural. Reintegro en caja de ahorro dentro de 10 días hábiles. Requiere caja de ahorro Galicia. Tope por cliente, incluye adicionales. Tope $25.000 por mes. Mínimo: los legales de Galicia dicen compras superiores a $35.000 (la ficha muestra $30.000) pero los T&C de la promo MODO de Changomás exigen $75.000: conviene comprar por $75.000 o más para asegurarlo. No acumulable.', false, '2026-11-17', '2026-12-31', 'https://beneficios.galicia.ar/promocion/191048%7Cchangomas%7Cmarca', 'media'),
  ('Galicia', 'Changomás', ARRAY['MasOnline'], ARRAY['lunes'], 20, 'reintegro', 25000, 'mes', 35000, 'Compras online en MasOnline (tienda online de Changomás) pagando con MODO desde App Galicia con tarjeta Galicia débito/crédito. Mismo tope mensual de $25.000 que la promo de locales (legales comparten el texto). Mínimo $35.000 según legales de Galicia ($30.000 en ficha; T&C MODO dicen $75.000). No acumulable.', true, '2026-11-17', '2026-12-31', 'https://beneficios.galicia.ar/promocion/191049%7Cmasonline%7Cmarca', 'media'),
  ('Galicia', 'Jumbo', '{}', ARRAY['martes', 'jueves'], 20, 'reintegro', 25000, 'mes', 100000, 'Pagando con QR de MODO desde App Galicia o App MODO con Tarjeta Galicia Débito Visa, Visa o Mastercard Galicia (crédito), en un pago. No aplica dinero en cuenta/transferencia ni Visa Business/Rural. Reintegro en caja de ahorro dentro de 10 días hábiles. Requiere caja de ahorro Galicia. Tope por cliente, incluye adicionales. Tope $25.000 por mes. No acumulable. Según T&C MODO vale QR o botón MODO (online).', NULL, '2026-11-04', '2026-11-30', 'https://beneficios.galicia.ar/promocion/189936%7Cjumbo%7Cmarca', 'alta'),
  ('Galicia', 'Disco', '{}', ARRAY['viernes', 'sábado'], 20, 'reintegro', 25000, 'mes', 100000, 'Pagando con QR de MODO desde App Galicia o App MODO con Tarjeta Galicia Débito Visa, Visa o Mastercard Galicia (crédito), en un pago. No aplica dinero en cuenta/transferencia ni Visa Business/Rural. Reintegro en caja de ahorro dentro de 10 días hábiles. Requiere caja de ahorro Galicia. Tope por cliente, incluye adicionales. Tope $25.000 por mes. Mínimo $100.000 según legales y T&C MODO (la ficha no lo muestra). No acumulable.', NULL, '2026-11-04', '2026-11-30', 'https://beneficios.galicia.ar/promocion/189932%7Cdisco%7Cmarca', 'alta'),
  ('Galicia', 'Vea', '{}', ARRAY['viernes'], 20, 'reintegro', 25000, 'mes', 100000, 'Pagando con QR de MODO desde App Galicia o App MODO con Tarjeta Galicia Débito Visa, Visa o Mastercard Galicia (crédito), en un pago. No aplica dinero en cuenta/transferencia ni Visa Business/Rural. Reintegro en caja de ahorro dentro de 10 días hábiles. Requiere caja de ahorro Galicia. Tope por cliente, incluye adicionales. Tope $25.000 por mes. No acumulable.', NULL, '2026-11-04', '2026-11-30', 'https://beneficios.galicia.ar/promocion/189933%7Cvea%7Cmarca', 'alta'),
